export declare const academicPaperTheme = "/* \u5B66\u672F\u8BBA\u6587\u98CE\u683C */\n#wemd {\n    padding: 5px 20px;\n    max-width: 677px;\n    margin: 0 auto;\n    /* \u6DF7\u5408\u5B57\u4F53\u6808\uFF1A\u897F\u6587Times + \u4E2D\u6587\u5B8B\u4F53 */\n    font-family: \"Times New Roman\", \"Songti SC\", \"SimSun\", serif;\n    color: #000;\n    background-color: transparent;\n    /* \u900F\u660E\u80CC\u666F\uFF0C\u517C\u5BB9\u5FAE\u4FE1\u6DF1\u8272\u6A21\u5F0F */\n    word-break: break-word;\n}\n\n/* \u6B63\u6587 - \u79FB\u9664\u9996\u884C\u7F29\u8FDB\uFF0C\u6539\u7528\u6BB5\u95F4\u8DDD\u9002\u5E94\u79FB\u52A8\u7AEF */\n#wemd p {\n    margin: 16px 0;\n    line-height: 1.7;\n    text-align: justify;\n    text-indent: 0;\n    color: #1a1a1a;\n    font-size: 16px;\n}\n\n/* \u4E00\u7EA7\u6807\u9898 - \u5C45\u4E2D\u8BBA\u6587\u9898 */\n#wemd h1 {\n    margin: 40px 0 30px;\n    text-align: center;\n    line-height: 1.4;\n}\n\n#wemd h1 .content {\n    font-size: 22px;\n    font-weight: bold;\n    color: #000;\n}\n\n#wemd h1 .prefix,\n#wemd h1 .suffix {\n    display: none;\n}\n\n/* \u4E8C\u7EA7\u6807\u9898 - \u7AE0\u8282 Section */\n#wemd h2 {\n    margin: 30px 0 15px;\n    text-align: left;\n    border-bottom: 2px solid #000;\n    /* \u52A0\u7C97\u5E95\u7EBF */\n    padding-bottom: 8px;\n}\n\n#wemd h2 .content {\n    font-size: 18px;\n    font-weight: bold;\n    color: #000;\n}\n\n#wemd h2 .prefix,\n#wemd h2 .suffix {\n    display: none;\n}\n\n/* \u4E09\u7EA7\u6807\u9898 - Subsection */\n#wemd h3 {\n    margin: 20px 0 10px;\n}\n\n#wemd h3 .content {\n    font-size: 16px;\n    font-weight: bold;\n    color: #800000;\n    /* \u6817\u8272\uFF0C\u533A\u5206\u5C42\u7EA7 */\n}\n\n#wemd h3 .prefix,\n#wemd h3 .suffix {\n    display: none;\n}\n\n/* \u56DB\u7EA7\u6807\u9898 */\n#wemd h4 {\n    margin: 15px 0 5px;\n}\n\n#wemd h4 .content {\n    font-size: 16px;\n    font-weight: bold;\n    font-style: italic;\n    /* \u659C\u4F53\u6807\u9898 */\n    color: #333;\n}\n\n#wemd h4 .prefix,\n#wemd h4 .suffix {\n    display: none;\n}\n\n/* \u5F15\u7528 - \u7B80\u6D01\u8FB9\u6846 */\n#wemd .multiquote-1 {\n    margin: 20px 0;\n    padding: 16px 20px;\n    background: #fafafa;\n    border: 1px solid #ddd;\n    border-left: 4px solid #666;\n}\n\n#wemd .multiquote-1 p {\n    color: #555;\n    font-size: 15px;\n    margin: 0;\n    line-height: 1.6;\n    text-indent: 0;\n}\n\n#wemd .multiquote-2 {\n    margin: 18px 0 18px 20px;\n    padding: 14px 18px;\n    background: #fafafa;\n    border: 1px solid #ddd;\n}\n\n#wemd .multiquote-2 p {\n    color: #555;\n    font-size: 15px;\n    margin: 0;\n}\n\n#wemd .multiquote-3 {\n    margin: 16px 0 16px 20px;\n    padding: 12px 16px;\n    background: #fcfcfc;\n    border: 1px solid #e0e0e0;\n}\n\n#wemd .multiquote-3 p {\n    color: #555;\n    font-size: 15px;\n    margin: 0;\n}\n\n/* \u5217\u8868 */\n#wemd ul {\n    list-style: disc;\n    padding-left: 20px;\n    margin: 16px 0;\n}\n\n#wemd ul ul {\n    list-style-type: square;\n    margin-top: 5px;\n}\n\n#wemd ol {\n    list-style: decimal;\n    padding-left: 20px;\n    margin: 16px 0;\n}\n\n#wemd ol ol {\n    list-style-type: lower-alpha;\n}\n\n#wemd li section {\n    color: #333;\n    line-height: 1.6;\n}\n\n/* \u94FE\u63A5 - \u7ECF\u5178\u6DF1\u84DD */\n#wemd a {\n    color: #000080;\n    text-decoration: underline;\n}\n\n/* \u52A0\u7C97 */\n#wemd strong {\n    color: #000;\n    font-weight: bold;\n}\n\n/* \u659C\u4F53 */\n#wemd em {\n    font-style: italic;\n    color: #000;\n}\n\n/* \u52A0\u7C97\u659C\u4F53 */\n#wemd em strong {\n    font-weight: bold;\n    font-style: italic;\n    color: #000;\n}\n\n/* \u9AD8\u4EAE - \u5B66\u672F\u6807\u8BB0\u98CE\u683C */\n#wemd mark {\n    background: #fff3cd;\n    color: #000;\n    padding: 0 2px;\n}\n\n/* \u5220\u9664\u7EBF */\n#wemd del {\n    text-decoration: line-through;\n    color: #666;\n    opacity: 0.7;\n}\n\n/* \u56FE\u7247 - \u7B80\u6D01\u65E0\u88C5\u9970 */\n#wemd img {\n    display: block;\n    margin: 30px auto;\n    width: 100%;\n    border: 1px solid #ddd;\n}\n\n#wemd figcaption {\n    margin-top: 8px;\n    text-align: center;\n    color: #666;\n    font-size: 14px;\n    font-style: italic;\n}\n\n/* \n * \u884C\u5185\u4EE3\u7801 - LaTeX \texttt \u98CE\u683C (\u4FEE\u590D\u91CD\u70B9)\n * \u7EAF\u9ED1\u6587\u5B57 + \u6781\u6DE1\u7070\u5E95 + \u7B49\u5BBD\u5B57\u4F53\n */\n#wemd p code,\n#wemd li code,\n#wemd td code,\n#wemd th code {\n    color: #000;\n    /* \u7EAF\u9ED1 */\n    background: #f4f4f4;\n    /* \u6781\u6DE1\u7070 */\n    border: 1px solid #eee;\n    /* \u6781\u7EC6\u8FB9\u6846 */\n    padding: 1px 4px;\n    margin: 0 2px;\n    border-radius: 2px;\n    font-size: 14px;\n    font-family: \"Courier New\", Courier, monospace;\n    /* \u5F3A\u5236\u7B49\u5BBD */\n}\n\n/* \u4EE3\u7801\u5757 - \u7B80\u5355\u7684\u5B66\u672F\u98CE\u683C */\n/* \u6CE8\u610F\uFF1A\u4E0D\u8981\u8BBE\u7F6E color\uFF0C\u8BA9\u8BED\u6CD5\u9AD8\u4EAE\u4E3B\u9898\u63A7\u5236\u6587\u5B57\u989C\u8272 */\n#wemd pre code.hljs {\n    background: #f9f9f9;\n    border: 1px solid #ccc;\n    /* color \u7531 .hljs \u8BED\u6CD5\u9AD8\u4EAE\u4E3B\u9898\u63A7\u5236 */\n    font-family: \"Courier New\", monospace;\n    font-size: 13px;\n    padding: 12px;\n    border-radius: 0;\n    /* \u76F4\u89D2 */\n    overflow-x: auto;\n    white-space: pre;\n  min-width: max-content;\n}\n\n/* \u5982\u679C\u6CA1\u6709\u8BED\u6CD5\u9AD8\u4EAE\uFF0C\u8BBE\u7F6E\u9ED8\u8BA4\u989C\u8272 */\n#wemd pre code:not(.hljs) {\n    color: #333;\n}\n\n/* \u8868\u683C - \u7ECF\u5178\u4E09\u7EBF\u8868 */\n#wemd table {\n    width: 100%;\n    border-collapse: collapse;\n    margin: 20px 0;\n    font-size: 14px;\n    border-top: 2px solid #000;\n    border-bottom: 2px solid #000;\n}\n\n#wemd table tr th {\n    border-bottom: 1px solid #000;\n    padding: 10px 5px;\n    font-weight: bold;\n    text-align: center;\n    background: #fff;\n}\n\n#wemd table tr td {\n    padding: 10px 5px;\n    border: none;\n    text-align: center;\n    color: #333;\n}\n\n/* \u9694\u884C\u5FAE\u5E95\u8272 */\n#wemd table tr:nth-child(even) td {\n    background-color: #fafafa;\n}\n\n/* \u811A\u6CE8 */\n#wemd .footnote-word,\n#wemd .footnote-ref {\n    color: #000080;\n}\n\n#wemd .footnotes-sep {\n    border-top: 1px solid #ccc;\n    padding-top: 10px;\n    margin-top: 40px;\n    width: 20%;\n    /* \u77ED\u7EBF */\n}\n\n#wemd .footnote-num {\n    font-weight: bold;\n    color: #000;\n    margin-right: 4px;\n    vertical-align: super;\n    font-size: 10px;\n}\n\n#wemd .footnote-item p {\n    color: #666;\n    font-size: 12px;\n    margin: 4px 0;\n}\n\n/* \u516C\u5F0F */\n#wemd .block-equation > svg {\n    max-width: 100% !important;\n}\n\n#wemd .inline-equation > svg {\n    max-width: 100%;\n    vertical-align: middle;\n}\n\n/* \u63D0\u793A\u5757 - \u5B66\u672F\u98CE\u683C */\n#wemd .callout {\n    margin: 20px 0;\n    padding: 16px 20px;\n    border: 1px solid #ddd;\n    border-radius: 0;\n    background: #fafafa;\n}\n\n#wemd .callout-title {\n    font-weight: bold;\n    margin-bottom: 8px;\n    font-size: 14px;\n    text-transform: uppercase;\n    color: #000;\n}\n\n#wemd .callout-icon { margin-right: 8px;\n    margin-right: 6px;\n}\n\n#wemd .callout-note { \n    border-left: 4px solid #666; \n    background: #f5f5f5;\n}\n\n#wemd .callout-tip { \n    border-left: 4px solid #555; \n    background: #f5f5f5;\n}\n\n#wemd .callout-important { \n    border-left: 4px solid #888; \n    background: #f5f5f5;\n}\n\n#wemd .callout-warning { \n    border-left: 4px solid #999; \n    background: #f5f5f5;\n}\n\n#wemd .callout-caution { \n    border-left: 4px solid #000; \n    background: #f5f5f5;\n}\n\n/* Imageflow CSS */\n#wemd .imageflow-layer1 {\n  margin-top: 1em;\n  margin-bottom: 0.5em;\n  /* white-space: normal; */\n  border: 0px none;\n  padding: 0px;\n  overflow: hidden;\n}\n\n#wemd .imageflow-layer2 {\n  white-space: nowrap;\n  width: 100%;\n  overflow-x: scroll;\n}\n\n#wemd .imageflow-layer3 {\n  display: inline-block;\n  word-wrap: break-word;\n  white-space: normal;\n  vertical-align: top;\n  width: 80%;\n  margin-right: 10px;\n  flex-shrink: 0;\n}\n\n#wemd .imageflow-img {\n  display: block;\n  width: 100%;\n  height: auto;\n  max-height: 300px;\n  object-fit: contain;\n  border-radius: 4px;\n}\n\n#wemd .imageflow-caption {\n  text-align: center;\n  margin-top: 0px;\n  padding-top: 0px;\n  color: #888;\n}\n";
